{
  "command": "mkdir -p /tmp/ext && python3 -c "
import docx
for n in ['skyvault-complaint','holt-eciaa-agreement','meridian-cd-response','pathforge-whitepaper-excerpt']:
    d = docx.Document('data/input_files/%s.docx'%n)
    out=[]
    for p in d.paragraphs:
        t=p.text.strip()
        if t and t!='&nbsp;': out.append(t)
    for ti,tb in enumerate(d.tables):
        out.append('[TABLE %d]'%ti)
        for r in tb.rows:
            out.append(' | '.join(c.text.strip() for c in r.cells))
    open('/tmp/ext/%s.txt'%n,'w').write('\n'.join(out))
    print(n, len(out))
"",
  "description": "Extract docx text to files"
}

